psr_crm_api = Blueprint("psr_crm_api", __name__)

_tables_ready = False
_public_hits: dict[str, list[float]] = defaultdict(list)


def ensure_crm_tables():
    global _tables_ready
    if _tables_ready:
        return
    try:
        ensure_hq_roles()
        CrmContact.__table__.create(bind=db.engine, checkfirst=True)
        CrmCase.__table__.create(bind=db.engine, checkfirst=True)
        CrmCaseContact.__table__.create(bind=db.engine, checkfirst=True)
        CrmEvent.__table__.create(bind=db.engine, checkfirst=True)
        CrmAssignment.__table__.create(bind=db.engine, checkfirst=True)
        _tables_ready = True
    except Exception as e:
        logger.warning("crm tables ensure failed: %s", e)


def _now():
    return datetime.now(timezone.utc).replace(tzinfo=None)


def _parse_dt(val):
    if not val:
        return None
    if isinstance(val, datetime):
        return val.replace(tzinfo=None) if val.tzinfo else val
    try:
        dt = date_parser.parse(str(val))
        return dt.replace(tzinfo=None) if dt.tzinfo else dt
    except Exception:
        return None


def _username() -> str:
    if current_user and current_user.is_authenticated:
        return current_user.username
    return "anonymous"


def _require_crm_read(fn):
    @wraps(fn)
    @auth_required()
    def wrapper(*args, **kwargs):
        ensure_crm_tables()
        if not can_crm_read():
            return forbid("CRM access denied")
        return fn(*args, **kwargs)

    return wrapper


def _require_crm_write(fn):
    @wraps(fn)
    @auth_required()
    def wrapper(*args, **kwargs):
        ensure_crm_tables()
        if not can_crm_write():
            return forbid("CRM write denied")
        return fn(*args, **kwargs)

    return wrapper


def _require_crm_command(fn):
    @wraps(fn)
    @auth_required()
    def wrapper(*args, **kwargs):
        ensure_crm_tables()
        if not can_crm_command():
            return forbid("CRM command denied")
        return fn(*args, **kwargs)

    return wrapper


def _require_reports(fn):
    @wraps(fn)
    @auth_required()
    def wrapper(*args, **kwargs):
        ensure_crm_tables()
        if not can_reports():
            return forbid("Reports access denied")
        return fn(*args, **kwargs)

    return wrapper


def _case_number() -> str:
    stamp = datetime.utcnow().strftime("%Y%m%d")
    return f"PSS-{stamp}-{uuid.uuid4().hex[:6].upper()}"


def _touch_first_response(case: CrmCase):
    if case.first_response_at is None and normalize_case_status(case.status) != "новый":
        case.first_response_at = _now()


def _case_json(case: CrmCase) -> dict:
    data = case.to_json()
    data["status"] = normalize_case_status(case.status)
    data["priority"] = normalize_priority(case.priority)
    data["source"] = normalize_source(case.source)
    return data


def _add_event(case_id: int, event_type: str, body: str | None = None, meta=None):
    ev = CrmEvent(
        case_id=case_id,
        event_type=event_type[:64],
        body=body,
        meta_json=json.dumps(meta, ensure_ascii=False) if meta is not None else None,
        created_by=_username(),
        created=_now(),
    )
    db.session.add(ev)
    return ev


def _get_case(case_id: int) -> CrmCase | None:
    return db.session.get(CrmCase, case_id)


def _rate_limit_public(ip: str, limit: int = 8, window: int = 600) -> bool:
    now = time.time()
    bucket = _public_hits[ip]
    _public_hits[ip] = [t for t in bucket if now - t < window]
    if len(_public_hits[ip]) >= limit:
        return False
    _public_hits[ip].append(now)
    return True


def _sanitize_mission_name(raw: str) -> str:
    base = re.sub(r"[^A-Za-z0-9_\-а-яА-ЯёЁ]+", "_", (raw or "").strip())[:80]
    return base or f"psr_{uuid.uuid4().hex[:8]}"


# ---------- me / roles ----------


@psr_crm_api.route("/api/crm/me", methods=["GET"])
@auth_required()
def crm_me():
    ensure_crm_tables()
    roles = sorted(_role_names())
    return jsonify(
        {
            "success": True,
            "username": _username(),
            "roles": roles,
            "hq_roles": [r for r in roles if r in HQ_ROLES or r == "administrator"],
            "can_read": can_crm_read(),
            "can_write": can_crm_write(),
            "can_command": can_crm_command(),
            "can_reports": can_reports(),
        }
    )


def _role_names():
    if not current_user or not current_user.is_authenticated:
        return []
    return [r.name for r in (current_user.roles or [])]


@psr_crm_api.route("/api/crm/hq/roles/bootstrap", methods=["POST"])
@auth_required()
def bootstrap_roles():
    if not has_any_role("administrator", ROLE_ADMIN):
        return forbid()
    ensure_hq_roles()
    return jsonify({"success": True, "roles": list(HQ_ROLES)})


@psr_crm_api.route("/api/crm/hq/assign_role", methods=["POST"])
@auth_required()
def assign_hq_role():
    if not has_any_role("administrator", ROLE_ADMIN):
        return forbid()
    ensure_hq_roles()
    body = request.get_json(silent=True) or {}
    username = (body.get("username") or "").strip()
    role_name = (body.get("role") or "").strip()
    action = (body.get("action") or "add").strip().lower()
    if not username or role_name not in HQ_ROLES:
        return jsonify({"success": False, "error": gettext("username and HQ role required")}), 400
    user = db.session.execute(db.session.query(User).filter_by(username=username)).scalar_one_or_none()
    if not user:
        return jsonify({"success": False, "error": gettext("User not found")}), 404
    ds = app.security.datastore
    role = ds.find_or_create_role(name=role_name)
    try:
        if action == "remove":
            ds.remove_role_from_user(user, role)
        else:
            ds.add_role_to_user(user, role)
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        return jsonify({"success": False, "error": str(e)}), 500
    return jsonify(
        {
            "success": True,
            "username": username,
            "roles": [r.name for r in user.roles],
        }
    )


# ---------- contacts ----------


@psr_crm_api.route("/api/crm/contacts", methods=["GET"])
@_require_crm_read
def list_contacts():
    q = (request.args.get("q") or "").strip().lower()
    rows = db.session.execute(db.session.query(CrmContact).order_by(CrmContact.id.desc())).scalars().all()
    if q:
        rows = [
            c
            for c in rows
            if q in (c.full_name or "").lower()
            or q in (c.phones or "").lower()
            or q in (c.email or "").lower()
        ]
    return jsonify({"success": True, "results": [c.to_json() for c in rows]})


@psr_crm_api.route("/api/crm/contacts", methods=["POST"])
@_require_crm_write
def create_contact():
    body = request.get_json(silent=True) or {}
    name = (body.get("full_name") or "").strip()
    if not name:
        return jsonify({"success": False, "error": gettext("Name required")}), 400
    role = normalize_contact_role(body.get("default_role") or "прочее")
    now = _now()
    c = CrmContact(
        full_name=name[:255],
        phones=(body.get("phones") or None),
        email=(body.get("email") or None),
        default_role=role,
        notes=(body.get("notes") or None),
        created_by=_username(),
        created=now,
        updated=now,
    )
    db.session.add(c)
    db.session.commit()
    return jsonify({"success": True, "result": c.to_json()}), 201


@psr_crm_api.route("/api/crm/contacts/<int:contact_id>", methods=["PUT", "PATCH"])
@_require_crm_write
def update_contact(contact_id: int):
    c = db.session.get(CrmContact, contact_id)
    if not c:
        return jsonify({"success": False, "error": gettext("Not found")}), 404
    body = request.get_json(silent=True) or {}
    for key in ("full_name", "phones", "email", "notes", "default_role"):
        if key in body and body[key] is not None:
            setattr(c, key, str(body[key])[:255] if key != "notes" else body[key])
    c.updated = _now()
    db.session.commit()
    return jsonify({"success": True, "result": c.to_json()})


@psr_crm_api.route("/api/crm/contacts/<int:contact_id>", methods=["DELETE"])
@_require_crm_command
def delete_contact(contact_id: int):
    c = db.session.get(CrmContact, contact_id)
    if not c:
        return jsonify({"success": False, "error": gettext("Not found")}), 404
    db.session.query(CrmCaseContact).filter_by(contact_id=contact_id).delete()
    db.session.delete(c)
    db.session.commit()
    return jsonify({"success": True})


# ---------- cases ----------


@psr_crm_api.route("/api/crm/cases", methods=["GET"])
@_require_crm_read
def list_cases():
    status = (request.args.get("status") or "").strip()
    assigned = (request.args.get("assigned") or "").strip()
    q = (request.args.get("q") or "").strip().lower()
    query = db.session.query(CrmCase).order_by(CrmCase.id.desc())
    rows = db.session.execute(query).scalars().all()
    if status:
        want = normalize_case_status(status)
        rows = [r for r in rows if normalize_case_status(r.status) == want]
    if assigned:
        rows = [r for r in rows if (r.assigned_username or "") == assigned]
    if q:
        rows = [
            r
            for r in rows
            if q in (r.case_number or "").lower()
            or q in (r.title or "").lower()
            or q in (r.missing_name or "").lower()
            or q in (r.reporter_phone or "").lower()
        ]
    return jsonify({"success": True, "results": [_case_json(r) for r in rows]})


@psr_crm_api.route("/api/crm/cases/<int:case_id>", methods=["GET"])
@_require_crm_read
def get_case(case_id: int):
    case = _get_case(case_id)
    if not case:
        return jsonify({"success": False, "error": gettext("Not found")}), 404
    events = (
        db.session.execute(
            db.session.query(CrmEvent).filter_by(case_id=case_id).order_by(CrmEvent.id.asc())
        )
        .scalars()
        .all()
    )
    links = (
        db.session.execute(db.session.query(CrmCaseContact).filter_by(case_id=case_id)).scalars().all()
    )
    contacts = []
    for link in links:
        c = db.session.get(CrmContact, link.contact_id)
        item = link.to_json()
        if c:
            item["contact"] = c.to_json()
        contacts.append(item)
    assignments = (
        db.session.execute(
            db.session.query(CrmAssignment).filter_by(case_id=case_id).order_by(CrmAssignment.id.desc())
        )
        .scalars()
        .all()
    )
    return jsonify(
        {
            "success": True,
            "result": _case_json(case),
            "events": [e.to_json() for e in events],
            "contacts": contacts,
            "assignments": [a.to_json() for a in assignments],
        }
    )


@psr_crm_api.route("/api/crm/cases", methods=["POST"])
@_require_crm_write
def create_case():
    body = request.get_json(silent=True) or {}
    title = (body.get("title") or body.get("missing_name") or "Обращение").strip()[:255]
    status = normalize_case_status(body.get("status") or "новый")
    priority = normalize_priority(body.get("priority") or "обычный")
    source = normalize_source(body.get("source") or "телефон")
    now = _now()
    case = CrmCase(
        case_number=_case_number(),
        status=status,
        priority=priority,
        source=source,
        title=title,
        summary=body.get("summary"),
        missing_name=(body.get("missing_name") or None),
        missing_age=(str(body["missing_age"])[:32] if body.get("missing_age") is not None else None),
        missing_sex=(body.get("missing_sex") or None),
        appearance=body.get("appearance"),
        clothing=body.get("clothing"),
        distinguishing=body.get("distinguishing"),
        medical=body.get("medical"),
        last_seen_at=_parse_dt(body.get("last_seen_at")),
        last_seen_place=body.get("last_seen_place"),
        lkp_lat=body.get("lkp_lat"),
        lkp_lon=body.get("lkp_lon"),
        reporter_name=body.get("reporter_name"),
        reporter_phone=body.get("reporter_phone"),
        assigned_username=body.get("assigned_username"),
        created_by=_username(),
        created=now,
        updated=now,
    )
    db.session.add(case)
    db.session.flush()
    _add_event(case.id, "created", f"Дело {case.case_number} создано")
    if case.reporter_name or case.reporter_phone:
        contact = CrmContact(
            full_name=(case.reporter_name or case.reporter_phone or "Заявитель")[:255],
            phones=case.reporter_phone,
            default_role="заявитель",
            created_by=_username(),
            created=now,
            updated=now,
        )
        db.session.add(contact)
        db.session.flush()
        db.session.add(
            CrmCaseContact(case_id=case.id, contact_id=contact.id, role_in_case="заявитель")
        )
    db.session.commit()
    return jsonify({"success": True, "result": _case_json(case)}), 201


@psr_crm_api.route("/api/crm/cases/<int:case_id>", methods=["PUT", "PATCH"])
@_require_crm_write
def update_case(case_id: int):
    case = _get_case(case_id)
    if not case:
        return jsonify({"success": False, "error": gettext("Not found")}), 404
    body = request.get_json(silent=True) or {}
    old_status = case.status
    for key in (
        "title",
        "summary",
        "missing_name",
        "missing_age",
        "missing_sex",
        "appearance",
        "clothing",
        "distinguishing",
        "medical",
        "last_seen_place",
        "reporter_name",
        "reporter_phone",
        "assigned_username",
        "closed_reason",
        "mission_name",
    ):
        if key in body:
            val = body[key]
            if key in ("title", "missing_name", "missing_age", "missing_sex", "reporter_name", "reporter_phone", "assigned_username", "mission_name"):
                setattr(case, key, (str(val)[:255] if val is not None else None))
            else:
                setattr(case, key, val)
    if "last_seen_at" in body:
        case.last_seen_at = _parse_dt(body.get("last_seen_at"))
    if "lkp_lat" in body:
        case.lkp_lat = body.get("lkp_lat")
    if "lkp_lon" in body:
        case.lkp_lon = body.get("lkp_lon")
    if "priority" in body:
        case.priority = normalize_priority(body["priority"])
    if "status" in body:
        case.status = normalize_case_status(body["status"])
    case.updated = _now()
    if case.status != old_status:
        _touch_first_response(case)
        _add_event(case.id, "status_change", f"{old_status} → {case.status}")
    else:
        _add_event(case.id, "updated", "Карточка обновлена")
    db.session.commit()
    return jsonify({"success": True, "result": _case_json(case)})


@psr_crm_api.route("/api/crm/cases/<int:case_id>/events", methods=["POST"])
@_require_crm_write
def add_case_event(case_id: int):
    case = _get_case(case_id)
    if not case:
        return jsonify({"success": False, "error": gettext("Not found")}), 404
    body = request.get_json(silent=True) or {}
    et = (body.get("event_type") or "comment")[:64]
    text = body.get("body") or body.get("comment") or ""
    _add_event(case_id, et, text, body.get("meta"))
    if case.first_response_at is None and et != "created":
        case.first_response_at = _now()
        case.updated = _now()
    db.session.commit()
    return jsonify({"success": True})


@psr_crm_api.route("/api/crm/cases/<int:case_id>/contacts", methods=["POST"])
@_require_crm_write
def link_case_contact(case_id: int):
    case = _get_case(case_id)
    if not case:
        return jsonify({"success": False, "error": gettext("Not found")}), 404
    body = request.get_json(silent=True) or {}
    contact_id = body.get("contact_id")
    if not contact_id:
        name = (body.get("full_name") or "").strip()
        if not name:
            return jsonify({"success": False, "error": gettext("contact_id or full_name required")}), 400
        now = _now()
        c = CrmContact(
            full_name=name[:255],
            phones=body.get("phones"),
            email=body.get("email"),
            default_role=normalize_contact_role(body.get("role_in_case") or "прочее"),
            notes=body.get("notes"),
            created_by=_username(),
            created=now,
            updated=now,
        )
        db.session.add(c)
        db.session.flush()
        contact_id = c.id
    role = normalize_contact_role(body.get("role_in_case") or "прочее")
    link = CrmCaseContact(
        case_id=case_id, contact_id=int(contact_id), role_in_case=role, notes=body.get("notes")
    )
    db.session.add(link)
    _add_event(case_id, "contact_linked", f"Контакт #{contact_id} ({role})")
    db.session.commit()
    return jsonify({"success": True, "result": link.to_json()}), 201


@psr_crm_api.route("/api/crm/cases/<int:case_id>/assign", methods=["POST"])
@_require_crm_write
def assign_case(case_id: int):
    case = _get_case(case_id)
    if not case:
        return jsonify({"success": False, "error": gettext("Not found")}), 404
    body = request.get_json(silent=True) or {}
    username = (body.get("username") or "").strip()
    if not username:
        return jsonify({"success": False, "error": gettext("username required")}), 400
    now = _now()
    # end previous active
    for a in (
        db.session.execute(
            db.session.query(CrmAssignment).filter_by(case_id=case_id, status="active")
        )
        .scalars()
        .all()
    ):
        a.status = "ended"
        a.ended = now
    asg = CrmAssignment(
        case_id=case_id,
        username=username[:255],
        shift_label=(body.get("shift_label") or None),
        status="active",
        assigned_by=_username(),
        created=now,
    )
    db.session.add(asg)
    case.assigned_username = username[:255]
    case.updated = now
    if normalize_case_status(case.status) == "новый":
        case.status = "разбор"
        _touch_first_response(case)
    _add_event(case_id, "assigned", f"Назначен {username}")
    db.session.commit()
    return jsonify({"success": True, "result": _case_json(case), "assignment": asg.to_json()})


@psr_crm_api.route("/api/crm/cases/<int:case_id>/link_mission", methods=["POST"])
@_require_crm_command
def link_mission(case_id: int):
    case = _get_case(case_id)
    if not case:
        return jsonify({"success": False, "error": gettext("Not found")}), 404
    body = request.get_json(silent=True) or {}
    mission_name = (body.get("mission_name") or "").strip()
    if not mission_name:
        return jsonify({"success": False, "error": gettext("mission_name required")}), 400
    mission = db.session.execute(
        db.session.query(Mission).filter_by(name=mission_name)
    ).scalar_one_or_none()
    if not mission:
        return jsonify({"success": False, "error": gettext("Mission not found")}), 404
    case.mission_name = mission_name
    if normalize_case_status(case.status) in ("новый", "разбор"):
        case.status = "активное"
        _touch_first_response(case)
    case.updated = _now()
    _add_event(case_id, "mission_linked", f"Привязана операция {mission_name}")
    db.session.commit()
    return jsonify({"success": True, "result": _case_json(case)})


def _ensure_subject_from_case(mission_name: str, case: CrmCase):
    from opentakserver.blueprints.ots_api.mission_ops_api import ensure_ops_tables

    ensure_ops_tables()
    name = (case.missing_name or case.title or "Пропавший")[:255]
    existing = (
        db.session.execute(
            db.session.query(MissionSubject).filter_by(mission_name=mission_name, status="active")
        )
        .scalars()
        .first()
    )
    now = _now()
    if existing:
        existing.full_name = name
        existing.age = case.missing_age
        existing.sex = case.missing_sex
        existing.clothing = case.clothing
        existing.appearance = case.appearance
        existing.distinguishing = case.distinguishing
        existing.medical = case.medical
        existing.last_seen_at = case.last_seen_at
        existing.last_seen_place = case.last_seen_place
        existing.notes = case.summary
        existing.updated = now
        return existing
    subj = MissionSubject(
        uid=str(uuid.uuid4()),
        mission_name=mission_name,
        full_name=name,
        age=case.missing_age,
        sex=case.missing_sex,
        clothing=case.clothing,
        appearance=case.appearance,
        distinguishing=case.distinguishing,
        medical=case.medical,
        last_seen_at=case.last_seen_at,
        last_seen_place=case.last_seen_place,
        notes=case.summary,
        status="active",
        created_by=_username(),
        created=now,
        updated=now,
    )
    db.session.add(subj)
    return subj


def _attach_groups(mission_name: str, group_names: list[str] | None = None):
    names = group_names or ["psr_shtab"]
    for gname in names:
        group = db.session.execute(db.session.query(Group).filter_by(name=gname)).scalar_one_or_none()
        if not group:
            continue
        exists = db.session.execute(
            db.session.query(GroupMission).filter_by(mission_name=mission_name, group_id=group.id)
        ).scalar_one_or_none()
        if exists:
            continue
        gm = GroupMission()
        gm.mission_name = mission_name
        gm.group_id = group.id
        db.session.add(gm)


@psr_crm_api.route("/api/crm/cases/<int:case_id>/create_mission", methods=["POST"])
@_require_crm_command
def create_mission_from_case(case_id: int):
    case = _get_case(case_id)
    if not case:
        return jsonify({"success": False, "error": gettext("Not found")}), 404
    body = request.get_json(silent=True) or {}
    if case.mission_name and not body.get("force"):
        return (
            jsonify(
                {
                    "success": False,
                    "error": gettext("Case already linked"),
                    "mission_name": case.mission_name,
                }
            ),
            400,
        )
    raw_name = body.get("mission_name") or case.case_number
    mission_name = _sanitize_mission_name(raw_name)
    existing = db.session.execute(
        db.session.query(Mission).filter_by(name=mission_name)
    ).scalar_one_or_none()
    if existing:
        mission_name = f"{mission_name}_{uuid.uuid4().hex[:4]}"

    creator_uid = body.get("creator_uid")
    if not creator_uid:
        eud = None
        if getattr(current_user, "id", None):
            eud = (
                db.session.execute(db.session.query(EUD).filter_by(user_id=current_user.id))
                .scalars()
                .first()
            )
        if not eud:
            eud = db.session.execute(db.session.query(EUD)).scalars().first()
        creator_uid = eud.uid if eud else None

    mission = Mission()
    mission.name = mission_name
    mission.description = (case.title or case.case_number)[:255]
    mission.create_time = datetime.now(timezone.utc)
    mission.guid = str(uuid.uuid4())
    mission.creator_uid = creator_uid
    mission.tool = "public"
    mission.default_role = MissionRole.MISSION_SUBSCRIBER
    mission.invite_only = False
    mission.password_protected = False
    mission.group = "__ANON__"
    db.session.add(mission)

    if creator_uid:
        role = MissionRole()
        role.clientUid = creator_uid
        role.username = _username()
        role.createTime = datetime.now(timezone.utc)
        role.role_type = MissionRole.MISSION_OWNER
        role.mission_name = mission_name
        db.session.add(role)
        inv = MissionInvitation()
        inv.mission_name = mission_name
        inv.client_uid = creator_uid
        inv.creator_uid = creator_uid
        inv.role = MissionRole.MISSION_OWNER
        db.session.add(inv)

    extra_groups = body.get("groups") or ["psr_shtab"]
    if isinstance(extra_groups, str):
        extra_groups = [extra_groups]
    db.session.flush()
    _attach_groups(mission_name, list(extra_groups))
    _ensure_subject_from_case(mission_name, case)

    case.mission_name = mission_name
    case.status = "активное"
    case.updated = _now()
    _touch_first_response(case)
    _add_event(case_id, "mission_created", f"Создана операция {mission_name}")
    db.session.commit()
    return jsonify(
        {
            "success": True,
            "result": _case_json(case),
            "mission_name": mission_name,
            "operation_url": f"/downloads/psr-operation.html?mission={mission_name}",
        }
    ), 201


# ---------- public report ----------


@psr_crm_api.route("/api/crm/public/report", methods=["POST"])
def public_report():
    ensure_crm_tables()
    ip = request.headers.get("X-Forwarded-For", request.remote_addr or "0.0.0.0").split(",")[0].strip()
    if not _rate_limit_public(ip):
        return jsonify({"success": False, "error": "Слишком много отправок. Подождите несколько минут"}), 429
    body = request.get_json(silent=True) or {}
    # honeypot
    if (body.get("website") or body.get("company") or "").strip():
        return jsonify({"success": True, "case_number": "OK"}), 201
    missing = (body.get("missing_name") or "").strip()
    reporter = (body.get("reporter_name") or "").strip()
    phone = (body.get("reporter_phone") or "").strip()
    place = (body.get("last_seen_place") or "").strip()
    if not missing or not phone:
        return (
            jsonify({"success": False, "error": "Укажите ФИО пропавшего и ваш телефон"}),
            400,
        )
    if len(phone) < 5 or len(missing) < 2:
        return jsonify({"success": False, "error": "Проверьте ФИО и телефон — слишком короткие или неверные"}), 400
    now = _now()
    title = f"Поиск: {missing}"[:255]
    case = CrmCase(
        case_number=_case_number(),
        status="новый",
        priority="обычный",
        source="веб",
        title=title,
        summary=(body.get("summary") or body.get("description") or None),
        missing_name=missing[:255],
        missing_age=(str(body["missing_age"])[:32] if body.get("missing_age") else None),
        missing_sex=(body.get("missing_sex") or None),
        appearance=body.get("appearance"),
        clothing=body.get("clothing"),
        distinguishing=body.get("distinguishing"),
        medical=body.get("medical"),
        last_seen_at=_parse_dt(body.get("last_seen_at")),
        last_seen_place=place or None,
        lkp_lat=body.get("lkp_lat"),
        lkp_lon=body.get("lkp_lon"),
        reporter_name=reporter[:255] if reporter else None,
        reporter_phone=phone[:64],
        created_by="public",
        created=now,
        updated=now,
    )
    db.session.add(case)
    db.session.flush()
    _add_event(case.id, "created", "Публичная форма")
    contact = CrmContact(
        full_name=(reporter or phone)[:255],
        phones=phone[:255],
        default_role="заявитель",
        created_by="public",
        created=now,
        updated=now,
    )
    db.session.add(contact)
    db.session.flush()
    db.session.add(CrmCaseContact(case_id=case.id, contact_id=contact.id, role_in_case="заявитель"))
    if missing:
        miss = CrmContact(
            full_name=missing[:255],
            default_role="пропавший",
            notes=case.summary,
            created_by="public",
            created=now,
            updated=now,
        )
        db.session.add(miss)
        db.session.flush()
        db.session.add(CrmCaseContact(case_id=case.id, contact_id=miss.id, role_in_case="пропавший"))
    db.session.commit()
    # do not leak internal ids beyond case_number
    return jsonify({"success": True, "case_number": case.case_number}), 201


# ---------- reports ----------


@psr_crm_api.route("/api/crm/reports/summary", methods=["GET"])
@_require_reports
def report_summary():
    rows = db.session.execute(db.session.query(CrmCase)).scalars().all()
    by_status: dict[str, int] = defaultdict(int)
    by_dispatcher: dict[str, int] = defaultdict(int)
    open_cases = []
    sla_samples = []
    for c in rows:
        by_status[normalize_case_status(c.status)] += 1
        if c.assigned_username:
            by_dispatcher[c.assigned_username] += 1
        if normalize_case_status(c.status) not in ("закрыто", "ложный"):
            open_cases.append(_case_json(c))
        if c.first_response_at and c.created:
            delta = (c.first_response_at - c.created).total_seconds()
            if delta >= 0:
                sla_samples.append(delta)
    avg_sla = sum(sla_samples) / len(sla_samples) if sla_samples else None
    return jsonify(
        {
            "success": True,
            "total": len(rows),
            "by_status": dict(by_status),
            "by_dispatcher": dict(by_dispatcher),
            "open_count": len(open_cases),
            "open_cases": open_cases,
            "avg_first_response_seconds": avg_sla,
            "sla_sample_count": len(sla_samples),
        }
    )


@psr_crm_api.route("/api/crm/reports/cases.csv", methods=["GET"])
@_require_reports
def report_cases_csv():
    rows = db.session.execute(db.session.query(CrmCase).order_by(CrmCase.id.desc())).scalars().all()
    buf = io.StringIO()
    w = csv.writer(buf)
    w.writerow(
        [
            "case_number",
            "status",
            "priority",
            "source",
            "title",
            "missing_name",
            "reporter_phone",
            "assigned_username",
            "mission_name",
            "created",
            "first_response_at",
            "updated",
        ]
    )
    for c in rows:
        w.writerow(
            [
                c.case_number,
                c.status,
                c.priority,
                c.source,
                c.title,
                c.missing_name,
                c.reporter_phone,
                c.assigned_username,
                c.mission_name,
                iso8601_string_from_datetime(c.created) if c.created else "",
                iso8601_string_from_datetime(c.first_response_at) if c.first_response_at else "",
                iso8601_string_from_datetime(c.updated) if c.updated else "",
            ]
        )
    data = buf.getvalue()
    return Response(
        data,
        mimetype="text/csv; charset=utf-8",
        headers={"Content-Disposition": "attachment; filename=crm_cases.csv"},
    )
